node_modules/next/dist/client/app-dir/link.js.map:1:{"version":3,"sources":["../../../src/client/app-dir/link.tsx"],"sourcesContent":["'use client'

import React, { createContext, useContext, useOptimistic, useRef } from 'react'
import type { UrlObject } from 'url'
