  installBindings().then(() =>
    loaderTransform.call(this, inputSource, inputSourceMap).then(
      ([transformedSource, outputSourceMap]: any) => {
        callback(null, transformedSource, outputSourceMap || inputSourceMap)
      },
      (err: Error) => {
        callback(err)
      }
    )
  )
}

