    'process.env.__NEXT_INSTANT_NAV_TOGGLE': isCacheComponentsEnabled,
    'process.env.__NEXT_EXPERIMENTAL_COLD_CACHE_BADGE': Boolean(
      config.experimental.coldCacheBadge
