        config.experimental.deferredEntries?.length &&
        deferredEntrypoints &&
        new DeferredEntriesPlugin({
          dev,
          config,
          deferredEntrypoints,
          deferredEntrySourceDirectories,
        }),
      isNodeServer &&
        new bundler.NormalModuleReplacementPlugin(
          /\.\/(.+)\.shared-runtime$/,
          function (resource) {
